package com.nextfeet.nextfeet.model; import java.math.BigDecimal; import java.time.LocalDate; public class Oferta { private Integer id; private String nombre,tipo,estado; private BigDecimal valor; private LocalDate fechaInicio,fechaFin; public Oferta(){} public Integer getId(){return id;} public void setId(Integer v){id=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public String getTipo(){return tipo;} public void setTipo(String v){tipo=v;} public BigDecimal getValor(){return valor;} public void setValor(BigDecimal v){valor=v;} public LocalDate getFechaInicio(){return fechaInicio;} public void setFechaInicio(LocalDate v){fechaInicio=v;} public LocalDate getFechaFin(){return fechaFin;} public void setFechaFin(LocalDate v){fechaFin=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }